import { GoogleGenAI, Type, Modality, Chat, GenerateContentResponse, LiveServerMessage, FunctionDeclaration, Content } from '@google/genai';
import { Persona } from '../types.ts';

const getAi = (): GoogleGenAI => {
    if (!process.env.API_KEY) {
        console.error("API_KEY environment variable not set.");
        throw new Error("API key is missing.");
    }
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

type LiveCallbacks = {
    onopen?: () => void;
    onmessage?: (message: LiveServerMessage) => void;
    onerror?: (e: ErrorEvent) => void;
    onclose?: (e: CloseEvent) => void;
};

const imageGenerationTool: FunctionDeclaration = {
    name: 'generateImage',
    parameters: {
        type: Type.OBJECT,
        description: 'Generates an image based on a textual description.',
        properties: {
            prompt: { type: Type.STRING, description: 'A detailed description of the image to generate.' },
            style: { type: Type.STRING, description: 'The artistic style, e.g., "photorealistic", "anime", "cartoon".' },
        },
        required: ['prompt'],
    },
};

const chatTools: { functionDeclarations: FunctionDeclaration[] }[] = [
    { functionDeclarations: [imageGenerationTool] }
];

export const GeminiService = {
    createChat: (systemInstruction?: string): Chat => {
        return getAi().chats.create({
            model: 'gemini-3-flash-preview',
            config: { 
                ...(systemInstruction && { systemInstruction }),
                tools: chatTools,
            },
        });
    },

    createChatWithHistory: (history: Content[], systemInstruction?: string): Chat => {
        return getAi().chats.create({
            model: 'gemini-3-flash-preview',
            history: history,
            config: { 
                ...(systemInstruction && { systemInstruction }),
                tools: chatTools,
            },
        });
    },

    getPersonaSuggestion: async (field: keyof Persona, currentPersona: Partial<Persona>): Promise<string> => {
        const personaContext = Object.entries(currentPersona)
            .filter(([, value]) => value)
            .map(([key, value]) => `${key}: ${value}`)
            .join(', ');

        const prompt = `Based on the following partial persona, suggest a creative value for "${field}".\n\nContext: ${personaContext || 'No details yet.'}`;

        const response = await getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt
        });

        return response.text.trim();
    },

    createPersonaFromText: async (description: string): Promise<Partial<Persona>> => {
        const prompt = `Extract character attributes into JSON:\n\n${description}`;

        const response = await getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        role: { type: Type.STRING },
                        personalityTraits: { type: Type.STRING },
                        physicalTraits: { type: Type.STRING },
                        lore: { type: Type.STRING },
                        characterDescription: { type: Type.STRING },
                        scenario: { type: Type.STRING },
                    }
                }
            }
        });

        return JSON.parse(response.text.trim());
    },

    summarizeConversation: async (history: Content[]): Promise<string> => {
        const conversationText = history
            .map(c => `${c.role}: ${c.parts.map(p => ('text' in p) ? p.text : '').join('')}`)
            .join('\n\n');

        const response = await getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Summarize this conversation concisely:\n\n${conversationText}`,
        });

        return response.text;
    },

    analyzeImage: async (prompt: string, imageBase64: string, mimeType: string): Promise<GenerateContentResponse> => {
        return getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [{ inlineData: { data: imageBase64, mimeType } }, { text: prompt }] },
        });
    },

    generateImage: async (prompt: string, aspectRatio: string, negativePrompt?: string): Promise<string[]> => {
        const response = await getAi().models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: `${prompt}${negativePrompt ? ` (avoid: ${negativePrompt})` : ''}` }] },
            config: { imageConfig: { aspectRatio: aspectRatio as any } }
        });
        const images: string[] = [];
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) images.push(part.inlineData.data);
        }
        return images;
    },

    analyzeVideo: async (prompt: string, videoBase64: string, mimeType: string): Promise<GenerateContentResponse> => {
        return getAi().models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: [{ inlineData: { data: videoBase64, mimeType } }, { text: prompt }] },
        });
    },

    transcribeAudio: async (audioBase64: string, mimeType: string): Promise<GenerateContentResponse> => {
        return getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [{ inlineData: { data: audioBase64, mimeType } }, { text: 'Transcribe this audio:' }] },
        });
    },

    analyzeDocument: async (text: string, prompt: string): Promise<GenerateContentResponse> => {
        return getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `${prompt}\n\nContent:\n${text}`,
        });
    },

    groundedSearch: async (prompt: string, useMaps: boolean, location?: {latitude: number, longitude: number}): Promise<GenerateContentResponse> => {
        const tools: any[] = [{ googleSearch: {} }];
        if (useMaps) tools.push({ googleMaps: {} });

        return getAi().models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                tools,
                ...(useMaps && location && { toolConfig: { retrievalConfig: { latLng: location } } }),
            },
        });
    },

    browseWebsite: async (url: string): Promise<string> => {
        try {
            const response = await fetch(url);
            const html = await response.text();
            const textContent = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            const summaryResponse = await getAi().models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Summarize this content:\n\n${textContent.substring(0, 10000)}`
            });
            return summaryResponse.text;
        } catch (error: any) {
            return `Failed to browse ${url}: ${error.message}`;
        }
    },

    complexReasoning: async (prompt: string): Promise<GenerateContentResponse> => {
        return getAi().models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { thinkingConfig: { thinkingBudget: 32768 } },
        });
    },

    connectLive: (callbacks: LiveCallbacks, voiceName: string, tools?: { functionDeclarations: FunctionDeclaration[] }[], customSystemInstruction?: string) => {
        return getAi().live.connect({
            model: 'gemini-2.5-flash-native-audio-preview-09-2025',
            callbacks,
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceName || 'Zephyr' } } },
                inputAudioTranscription: {},
                outputAudioTranscription: {},
                systemInstruction: customSystemInstruction,
                ...(tools && { tools }),
            },
        });
    }
};

import React, { useState, useEffect } from 'react';
import FeatureLayout from './common/FeatureLayout.tsx';
import { dbService } from '../services/dbService.ts';
import { cryptoService } from '../services/cryptoService.ts';
import { DownloadIcon, UploadIcon, EditIcon, TrashIcon, ShareIcon } from '../components/Icons.tsx';
import { Persona } from '../types.ts';
import PersonaConfigModal from './common/PersonaConfigModal.tsx';
import PasswordPromptModal from '../components/PasswordPromptModal.tsx';
import { LIVE_VOICES } from '../constants.ts';

const findJsonInPng = (arrayBuffer: ArrayBuffer): string | null => {
    const dataView = new DataView(arrayBuffer);
    if (dataView.getUint32(0) !== 0x89504E47) return null;

    let offset = 8;
    const decoderLatin1 = new TextDecoder('latin1');
    while (offset < dataView.byteLength) {
        const length = dataView.getUint32(offset);
        const type = new TextDecoder().decode(new Uint8Array(arrayBuffer, offset + 4, 4));
        if (type === 'tEXt') {
            const chunkData = new Uint8Array(arrayBuffer, offset + 8, length);
            const text = decoderLatin1.decode(chunkData);
            const splitIndex = text.indexOf('\0');
            if (splitIndex > -1) {
                const keyword = text.substring(0, splitIndex);
                if (keyword === 'chara') return atob(text.substring(splitIndex + 1));
            }
        }
        if (type === 'IEND') break;
        offset += 12 + length; 
    }
    return null;
};

const processLorebook = (characterBook: any): string => {
    if (!characterBook || !characterBook.entries) return '';
    let loreText = '\n\n[World Info / Lorebook]:\n';
    characterBook.entries.forEach((entry: any) => {
        if (entry.enabled === false) return;
        loreText += `\n--- ${entry.name || 'Entry'} ---\nKeywords: ${entry.keys?.join(', ') || ''}\n${entry.content || ''}\n`;
    });
    return loreText;
};

const Settings: React.FC = () => {
    const [isExporting, setIsExporting] = useState(false);
    const [isImporting, setIsImporting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);
    const [personas, setPersonas] = useState<Persona[]>([]);
    const [selectedVoice, setSelectedVoice] = useState<string>('Zephyr');
    const [isPersonaModalOpen, setIsPersonaModalOpen] = useState(false);
    const [editingPersona, setEditingPersona] = useState<Persona | null>(null);
    const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
    const [passwordModalConfig, setPasswordModalConfig] = useState<any>({});

    useEffect(() => {
        dbService.getPersonas().then(setPersonas);
        dbService.getVoicePreference().then(v => v && setSelectedVoice(v));
    }, []);

    const handleExport = () => {
        setPasswordModalConfig({
            title: "Set Backup Password",
            description: "Required to decrypt your backup file.",
            buttonText: "Export",
            onSubmit: async (pw: string) => {
                const data = await dbService.getAllDataForBackup();
                const encrypted = await cryptoService.encryptBackup(data, pw);
                const blob = new Blob([encrypted], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `gemini-backup-${new Date().toISOString().split('T')[0]}.json`;
                a.click();
                setIsPasswordModalOpen(false);
            }
        });
        setIsPasswordModalOpen(true);
    };

    const handleImportRequest = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            const content = e.target?.result as string;
            setPasswordModalConfig({
                title: "Enter Password",
                description: "Password for the backup file.",
                buttonText: "Import",
                onSubmit: async (pw: string) => {
                    try {
                        const data = await cryptoService.decryptBackup(content, pw);
                        await dbService.importAndOverwriteAllData(data);
                        window.location.reload();
                    } catch (err) { setError("Import failed: Incorrect password."); }
                    setIsPasswordModalOpen(false);
                }
            });
            setIsPasswordModalOpen(true);
        };
        reader.readAsText(file);
    };

    const handleSavePersona = async (p: Persona) => {
        const updated = personas.some(existing => existing.id === p.id) 
            ? personas.map(e => e.id === p.id ? p : e) 
            : [...personas, p];
        if (updated.length === 1) updated[0].isActive = true;
        setPersonas(updated);
        await dbService.savePersonas(updated);
        window.dispatchEvent(new CustomEvent('personasUpdated'));
    };

    const handleDeletePersona = async (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        if (!window.confirm("Delete this character?")) return;
        const updated = personas.filter(p => p.id !== id);
        if (personas.find(p => p.id === id)?.isActive && updated.length > 0) updated[0].isActive = true;
        setPersonas(updated);
        await dbService.savePersonas(updated);
        window.dispatchEvent(new CustomEvent('personasUpdated'));
    };

    const handleSetActive = async (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        const updated = personas.map(p => ({ ...p, isActive: p.id === id }));
        setPersonas(updated);
        await dbService.savePersonas(updated);
        window.dispatchEvent(new CustomEvent('personasUpdated'));
    };

    const handleImportCharacter = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;
        setError(null); setSuccess(null);
        try {
            let fileContent = '';
            if (file.name.endsWith('.json')) fileContent = await file.text();
            else if (file.name.endsWith('.png')) {
                const json = findJsonInPng(await file.arrayBuffer());
                if (!json) throw new Error("No character data in PNG.");
                fileContent = json;
            }
            const data = JSON.parse(fileContent);
            if (!data) throw new Error("Empty character file.");

            let imported: Partial<Persona> = {};
            if (data.spec === 'chara_card_v2' && data.data) {
                const d = data.data;
                imported = {
                    role: d.name,
                    characterDescription: d.first_mes,
                    personalityTraits: d.personality,
                    scenario: d.scenario,
                    lore: (d.description || '') + processLorebook(d.character_book),
                    systemPrompt: d.mes_example
                };
            } else if (data.name || data.char_name) {
                imported = {
                    role: data.name || data.char_name,
                    characterDescription: data.first_mes || data.char_greeting,
                    personalityTraits: data.personality || data.char_persona,
                    scenario: data.scenario || data.world_scenario,
                    lore: data.description || '',
                    systemPrompt: data.mes_example || data.example_dialogue
                };
            } else {
                throw new Error("Unknown character card format.");
            }

            if (!imported.role) throw new Error("Character card missing name.");

            const complete: Persona = {
                id: crypto.randomUUID(),
                isActive: false,
                role: imported.role,
                personalityTraits: imported.personalityTraits || '',
                physicalTraits: imported.physicalTraits || '',
                lore: imported.lore || '',
                characterDescription: imported.characterDescription || '',
                scenario: imported.scenario || '',
                systemPrompt: imported.systemPrompt || '',
                avatarUrl: '',
                voice: ''
            };
            await handleSavePersona(complete);
            setSuccess(`Imported "${complete.role}"`);
        } catch (err: any) { setError(err.message); }
        event.target.value = '';
    };

    return (
        <FeatureLayout title="Settings" description="Manage characters and data.">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-slate-800/50 rounded-lg p-6 flex flex-col h-[500px]">
                    <h2 className="text-xl font-bold mb-3 text-white">Characters</h2>
                    <div className="flex-grow overflow-y-auto pr-2 space-y-2">
                        {personas.map(p => (
                            <div key={p.id} onClick={() => { setEditingPersona(p); setIsPersonaModalOpen(true); }} className={`p-3 rounded-lg flex items-center justify-between cursor-pointer group ${p.isActive ? 'bg-blue-900/50 ring-1 ring-blue-500' : 'bg-slate-700/50 hover:bg-slate-700'}`}>
                                <div className="flex items-center space-x-3 overflow-hidden">
                                    <div className="w-10 h-10 rounded-full bg-slate-600 flex-shrink-0 flex items-center justify-center font-bold">
                                        {p.avatarUrl ? <img src={p.avatarUrl} className="w-full h-full rounded-full object-cover" /> : p.role.charAt(0)}
                                    </div>
                                    <div className="truncate">
                                        <p className="font-semibold truncate">{p.role}</p>
                                        <p className="text-xs text-slate-400 truncate">{p.personalityTraits || 'No traits set'}</p>
                                    </div>
                                </div>
                                <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity" onClick={e => e.stopPropagation()}>
                                    {!p.isActive && <button onClick={(e) => handleSetActive(e, p.id)} className="text-xs bg-green-600 text-white px-2 py-1 rounded">Set</button>}
                                    <button onClick={(e) => handleDeletePersona(e, p.id)} className="p-2 hover:bg-red-600 rounded"><TrashIcon/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="mt-4 flex flex-wrap gap-2">
                        <button onClick={() => { setEditingPersona({ id: crypto.randomUUID(), role: 'New Hero', personalityTraits: '', physicalTraits: '', lore: '', characterDescription: '', scenario: '', systemPrompt: '', avatarUrl: '', voice: '' }); setIsPersonaModalOpen(true); }} className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 rounded-lg text-sm">Create</button>
                        <input type="file" id="import-char" className="hidden" accept=".json,.png" onChange={handleImportCharacter} />
                        <label htmlFor="import-char" className="flex-1 bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 rounded-lg text-sm text-center cursor-pointer">Import Card</label>
                    </div>
                    {success && <p className="text-green-400 text-xs mt-2">{success}</p>}
                    {error && <p className="text-red-400 text-xs mt-2">{error}</p>}
                </div>
                <div className="bg-slate-800/50 rounded-lg p-6 flex flex-col h-[500px]">
                    <h2 className="text-xl font-bold mb-3 text-white">Preferences & Backup</h2>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm text-slate-400 mb-1">Live Voice</label>
                            <select value={selectedVoice} onChange={(e) => { setSelectedVoice(e.target.value); dbService.saveVoicePreference(e.target.value); }} className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3">
                                {LIVE_VOICES.map(v => <option key={v} value={v}>{v}</option>)}
                            </select>
                        </div>
                        <div className="pt-4 border-t border-slate-700 flex gap-4">
                            <button onClick={handleExport} className="flex-1 bg-slate-700 hover:bg-slate-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2"><DownloadIcon/> Export All</button>
                            <input type="file" id="import-all" className="hidden" accept=".json" onChange={handleImportRequest} />
                            <label htmlFor="import-all" className="flex-1 bg-slate-700 hover:bg-slate-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 cursor-pointer"><UploadIcon/> Import All</label>
                        </div>
                    </div>
                </div>
            </div>
            {isPersonaModalOpen && editingPersona && (
                <PersonaConfigModal isOpen={isPersonaModalOpen} onClose={() => setIsPersonaModalOpen(false)} initialPersona={editingPersona} onSave={handleSavePersona} />
            )}
            <PasswordPromptModal isOpen={isPasswordModalOpen} onClose={() => setIsPasswordModalOpen(false)} {...passwordModalConfig} />
        </FeatureLayout>
    );
};
export default Settings;

import React, { useState } from 'react';
import FeatureLayout from './common/FeatureLayout.tsx';
import { formatBytes, fileToBase64, encode } from '../utils/helpers.ts';
import { FileTextIcon, ArchiveIcon, TrashIcon } from '../components/Icons.tsx';
import { dbService, StoredFile } from '../services/dbService.ts';

interface FileLibraryProps {
    documents: StoredFile[];
    setDocuments: React.Dispatch<React.SetStateAction<StoredFile[]>>;
}

const FileLibrary: React.FC<FileLibraryProps> = ({ documents, setDocuments }) => {
    const [view, setView] = useState<'active' | 'archived'>('active');

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files) return;
        const newFiles = Array.from(files);
        try {
            const filesToStore: StoredFile[] = await Promise.all(newFiles.map(async (file) => {
                let base64Data = await fileToBase64(file);
                let fileType = file.type;
                let fileName = file.name;

                // Lorebook Detection & Conversion
                if (file.name.toLowerCase().endsWith('.json')) {
                    try {
                        const text = await file.text();
                        const json = JSON.parse(text);
                        if (json.entries && Array.isArray(json.entries)) {
                            let loreText = `[WORLD INFO / LOREBOOK: ${fileName}]\n`;
                            json.entries.forEach((entry: any) => {
                                if (entry.enabled === false) return;
                                loreText += `\n--- ${entry.name || 'Entry'} ---\nKeys: ${entry.keys?.join(', ') || 'Global'}\n${entry.content || ''}\n`;
                            });
                            const contentBytes = new TextEncoder().encode(loreText);
                            base64Data = encode(contentBytes);
                            fileType = 'text/plain';
                            fileName = fileName.replace('.json', '.txt');
                            if (!fileName.includes('(Lore)')) fileName = fileName.replace('.txt', ' (Lore).txt');
                        }
                    } catch (e) { console.warn("JSON parse failed during lorebook check."); }
                }

                return {
                    name: fileName,
                    type: fileType,
                    size: file.size,
                    lastModified: file.lastModified,
                    isArchived: false,
                    data: base64Data,
                };
            }));
            await dbService.addDocuments(filesToStore);
            setDocuments(prev => [...prev, ...filesToStore]);
        } catch (error) { alert("Failed to save files."); }
    };

    const handleRemoveDocument = async (name: string) => {
        if (!window.confirm(`Delete "${name}"?`)) return;
        await dbService.removeDocument(name);
        setDocuments(prev => prev.filter(f => f.name !== name));
    };

    const handleArchiveToggle = async (file: StoredFile) => {
        const updated = { ...file, isArchived: !file.isArchived };
        await dbService.updateDocument(updated);
        setDocuments(prev => prev.map(f => f.name === file.name ? updated : f));
    };

    const displayed = documents.filter(doc => view === 'active' ? !doc.isArchived : doc.isArchived);

    return (
        <FeatureLayout title="File Library" description="Upload lorebooks, images, or docs for AI reference.">
            <div className="max-w-4xl mx-auto">
                <div className="w-full p-8 border-2 border-dashed border-slate-600 rounded-lg text-center mb-8 bg-slate-800/50 hover:border-blue-500 transition-colors">
                    <input type="file" accept=".txt,.pdf,.png,.jpg,.jpeg,.webp,.mp4,.mp3,.wav,.json" onChange={handleFileChange} className="hidden" id="lib-upload" multiple />
                    <label htmlFor="lib-upload" className="cursor-pointer">
                        <FileTextIcon />
                        <p className="mt-2 font-semibold">Click to upload Lorebooks (.json) or Media</p>
                    </label>
                </div>
                <div className="flex border-b border-slate-700 mb-4">
                    <button onClick={() => setView('active')} className={`py-2 px-4 font-semibold ${view === 'active' ? 'text-white border-b-2 border-blue-500' : 'text-slate-400'}`}>Active</button>
                    <button onClick={() => setView('archived')} className={`py-2 px-4 font-semibold ${view === 'archived' ? 'text-white border-b-2 border-blue-500' : 'text-slate-400'}`}>Archived</button>
                </div>
                <ul className="space-y-3">
                    {displayed.map(doc => (
                        <li key={doc.name} className="flex items-center justify-between p-4 bg-slate-800 rounded-lg">
                            <div className="flex items-center space-x-4 overflow-hidden">
                                <FileTextIcon />
                                <div className="truncate">
                                    <p className="font-semibold text-slate-200 truncate">{doc.name}</p>
                                    <p className="text-xs text-slate-400">{formatBytes(doc.size)}</p>
                                </div>
                            </div>
                            <div className="flex items-center space-x-2 flex-shrink-0">
                                <button onClick={() => handleArchiveToggle(doc)} className="text-slate-400 hover:text-white p-2" title="Archive"><ArchiveIcon /></button>
                                <button onClick={() => handleRemoveDocument(doc.name)} className="text-slate-400 hover:text-red-500 p-2" title="Delete"><TrashIcon /></button>
                            </div>
                        </li>
                    ))}
                </ul>
            </div>
        </FeatureLayout>
    );
};
export default FileLibrary;

import React, { useState } from 'react';
import FeatureLayout from './common/FeatureLayout.tsx';
import { formatBytes, fileToBase64, encode } from '../utils/helpers.ts';
import { FileTextIcon, ArchiveIcon, TrashIcon } from '../components/Icons.tsx';
import { dbService, StoredFile } from '../services/dbService.ts';

interface FileLibraryProps {
    documents: StoredFile[];
    setDocuments: React.Dispatch<React.SetStateAction<StoredFile[]>>;
}

const FileLibrary: React.FC<FileLibraryProps> = ({ documents, setDocuments }) => {
    const [view, setView] = useState<'active' | 'archived'>('active');

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files) return;
        // FIX: Explicitly cast Array.from(files) to File[] to resolve type 'unknown' errors when accessing file properties.
        const newFiles = Array.from(files) as File[];
        try {
            const filesToStore: StoredFile[] = await Promise.all(newFiles.map(async (file) => {
                let base64Data = await fileToBase64(file);
                let fileType = file.type;
                let fileName = file.name;

                // Lorebook Detection & Conversion
                if (file.name.toLowerCase().endsWith('.json')) {
                    try {
                        const text = await file.text();
                        const json = JSON.parse(text);
                        if (json.entries && Array.isArray(json.entries)) {
                            let loreText = `[WORLD INFO / LOREBOOK: ${fileName}]\n`;
                            json.entries.forEach((entry: any) => {
                                if (entry.enabled === false) return;
                                loreText += `\n--- ${entry.name || 'Entry'} ---\nKeys: ${entry.keys?.join(', ') || 'Global'}\n${entry.content || ''}\n`;
                            });
                            const contentBytes = new TextEncoder().encode(loreText);
                            base64Data = encode(contentBytes);
                            fileType = 'text/plain';
                            fileName = fileName.replace('.json', '.txt');
                            if (!fileName.includes('(Lore)')) fileName = fileName.replace('.txt', ' (Lore).txt');
                        }
                    } catch (e) { console.warn("JSON parse failed during lorebook check."); }
                }

                return {
                    name: fileName,
                    type: fileType,
                    size: file.size,
                    lastModified: file.lastModified,
                    isArchived: false,
                    data: base64Data,
                };
            }));
            await dbService.addDocuments(filesToStore);
            setDocuments(prev => [...prev, ...filesToStore]);
        } catch (error) { alert("Failed to save files."); }
    };

    const handleRemoveDocument = async (name: string) => {
        if (!window.confirm(`Delete "${name}"?`)) return;
        await dbService.removeDocument(name);
        setDocuments(prev => prev.filter(f => f.name !== name));
    };

    const handleArchiveToggle = async (file: StoredFile) => {
        const updated = { ...file, isArchived: !file.isArchived };
        await dbService.updateDocument(updated);
        setDocuments(prev => prev.map(f => f.name === file.name ? updated : f));
    };

    const displayed = documents.filter(doc => view === 'active' ? !doc.isArchived : doc.isArchived);

    return (
        <FeatureLayout title="File Library" description="Upload lorebooks, images, or docs for AI reference.">
            <div className="max-w-4xl mx-auto">
                <div className="w-full p-8 border-2 border-dashed border-slate-600 rounded-lg text-center mb-8 bg-slate-800/50 hover:border-blue-500 transition-colors">
                    <input type="file" accept=".txt,.pdf,.png,.jpg,.jpeg,.webp,.mp4,.mp3,.wav,.json" onChange={handleFileChange} className="hidden" id="lib-upload" multiple />
                    <label htmlFor="lib-upload" className="cursor-pointer">
                        <FileTextIcon />
                        <p className="mt-2 font-semibold">Click to upload Lorebooks (.json) or Media</p>
                    </label>
                </div>
                <div className="flex border-b border-slate-700 mb-4">
                    <button onClick={() => setView('active')} className={`py-2 px-4 font-semibold ${view === 'active' ? 'text-white border-b-2 border-blue-500' : 'text-slate-400'}`}>Active</button>
                    <button onClick={() => setView('archived')} className={`py-2 px-4 font-semibold ${view === 'archived' ? 'text-white border-b-2 border-blue-500' : 'text-slate-400'}`}>Archived</button>
                </div>
                <ul className="space-y-3">
                    {displayed.map(doc => (
                        <li key={doc.name} className="flex items-center justify-between p-4 bg-slate-800 rounded-lg">
                            <div className="flex items-center space-x-4 overflow-hidden">
                                <FileTextIcon />
                                <div className="truncate">
                                    <p className="font-semibold text-slate-200 truncate">{doc.name}</p>
                                    <p className="text-xs text-slate-400">{formatBytes(doc.size)}</p>
                                </div>
                            </div>
                            <div className="flex items-center space-x-2 flex-shrink-0">
                                <button onClick={() => handleArchiveToggle(doc)} className="text-slate-400 hover:text-white p-2" title="Archive"><ArchiveIcon /></button>
                                <button onClick={() => handleRemoveDocument(doc.name)} className="text-slate-400 hover:text-red-500 p-2" title="Delete"><TrashIcon /></button>
                            </div>
                        </li>
                    ))}
                </ul>
            </div>
        </FeatureLayout>
    );
};
